", "t": [["write_file", "{"path":"D:\\Projects\\local_ai\\strata-lab\\runs\\work\\hermes\\jsondiff-1794053379\\jsondiff.py","content":"import json\n\n\ndef _kind(value):\n    if isinstance(value, dict):\n        return \"dict\"\n    if isinstance(value, list):\n        return \"list\"\n    return None\n\n\ndef _same(a, b):\n    # Equal only when the types match exactly (so 1, 1.0, True and \"1\" all differ).\n    if type(a) is not type(b):\n        return False\n    return a == b\n\n\ndef _render(value):\n    return json.dumps(value, sort_keys=True)\n\n\ndef _walk(a, b, path, out):\n    if _kind(a) == \"dict\" and _kind(b) == \"dict\":\n        for key in set(a) | set(b):\n            child = \"{}.{}\".format(path, key)\n            if key not in b:\n                out.append(\"- {}: {}\".format(child, _render(a[key])))\n            elif key not in a:\n                out.append(\"+ {}: {}\".format(child, _render(b[key])))\n            else:\n                _walk(a[key], b[key], child, out)\n    elif _kind(a) == \"list\" and _kind(b) == \"list\":\n        common = min(len(a), len(b))\n        for i in range(common):\n            _walk(a[i], b[i], \"{}[{}]\".format(path, i), out)\n        for i in range(common, len(a)):\n            out.append(\"- {}[{}]: {}\".format(path, i, _render(a[i])))\n        for i in range(common, len(b)):\n            out.append(\"+ {}[{}]: {}\".format(path, i, _render(b[i])))\n    elif not _same(a, b):\n        out.append(\"~ {}: {} -> {}\".format(path, _render(a), _render(b)))\n\n\ndef diff(a, b):\n    out = []\n    _walk(a, b, \"$\", out)\n    return sorted(out)\n"}"]]}
